package com.dndmaster.ruleknowledge; import static org.junit.jupiter.api.Assertions.*; import com.dndmaster.ruleknowledge.api.ApiRequestGuard; import java.util.UUID; import org.junit.jupiter.api.Test;
class ApiSecurityIntegrationTest{@Test void validates_authentication_ownership_internal_token_and_request(){var g=new ApiRequestGuard("service-secret");var owner=UUID.randomUUID();g.publicOwner("Bearer token",owner,owner);g.internal("service-secret");assertEquals(400,assertThrows(ApiRequestGuard.ApiContractException.class,()->ApiRequestGuard.required(" ","file")).status());assertEquals(401,assertThrows(ApiRequestGuard.ApiContractException.class,()->g.publicOwner("",owner,owner)).status());assertEquals(403,assertThrows(ApiRequestGuard.ApiContractException.class,()->g.publicOwner("Bearer x",owner,UUID.randomUUID())).status());assertEquals(401,assertThrows(ApiRequestGuard.ApiContractException.class,()->g.internal("wrong")).status());}}
